      # A `DocumentGroup` contains the documents after they have been filled and sent out for signature. The
      # `DocumentGroup` will only exist here when that documents have been sent out for signature, or in the case of a
      # workflow with no signers, when the workflow is completely finished. See the `DocumentGroup`'s `status` for
      # lifecycle information.
      attribute :document_group, type: Anvil::Types::DocumentGroup

