      # `DocumentGroup.files`.
      attribute :files

      attribute :forges_requiring_completion, array_of: Anvil::Types::Forge
      attribute :has_pin
      attribute :has_signers

      # `true` when status is `completed`: All forms have been filled, all signers have signed.
      attribute :is_all_complete

      # `true` when all forms in the workflow have been filled. There may be signers who need to sign.
      attribute :is_complete

      # This `WeldData` has expired, either by passing the `expiredAt` date, or by being locked.
      attribute :is_expired

      # `true` when it is a test workflow submission. You will not be charged for signatures on test submissions, and
      # they will not count toward your monthly completed workflows.
      attribute :is_test

      attribute :next_signer, type: Anvil::Types::Signer
      attribute :next_signers, array_of: Anvil::Types::Signer
      attribute :number_remaining_signers
