      attribute :submissions, array_of: Anvil::Types::Submission

      # When a column on the WeldData itself was updated.
      attribute :updated_at, type: :time

      # An array of files uploaded by users during the webform filling process.
      attribute :user_uploads, array_of: Anvil::Types::UserUpload

      # An array of webhook notification calls to your server related to this `WeldData`. Get the status codes, response
