      attribute :webhook_logs, array_of: Anvil::Types::WebhookLog

      # The specific webhook notification URL for this `WeldData`. We will POST to this URL when users take various
      # actions.
      attribute :webhook_url, key: "webhookURL"

      # The workflow this `WeldData` is related to.
      attribute :weld, type: Anvil::Types::Weld

      attribute :weld_data_group, type: Anvil::Types::WeldDataGroup

