    # The file a `download` returns.
    module DownloadFormat
      PDF = "pdf"
      ZIP = "zip"

      VALUES = [PDF, ZIP].freeze
    end

    # What an eid passed to `download` refers to.
    module DownloadObjectType
      # The same object as `document_template`, under the name the API uses.
      CAST = "cast"
      # The same object as `esign_documents`, under the name the API uses.
      DOCUMENT_GROUP = "document_group"
      # Downloads as pdf.
      DOCUMENT_TEMPLATE = "document_template"
      # Downloads as zip.
      ESIGN_DOCUMENTS = "esign_documents"

      VALUES = [CAST, DOCUMENT_GROUP, DOCUMENT_TEMPLATE, ESIGN_DOCUMENTS].freeze
    end
